#include <stdio.h>

#define MAX_VAL 100005

int last_pos[MAX_VAL];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int max_len = 0;
    int l = 1;

    for (int r = 1; r <= n; r++) {
        int x;
        scanf("%d", &x);

        if (last_pos[x] >= l) {
            l = last_pos[x] + 1;
        }

        int current_len = r - l + 1;
        if (current_len > max_len) {
            max_len = current_len;
        }

        last_pos[x] = r;
    }

    printf("%d\n", max_len);

    return 0;
}
